        var saved=AppearanceManager.Current;var panel=new StackPanel{Margin=new(12)};panel.Children.Add(new TextBlock{Text="Giao diện & màu sắc",FontSize=22,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text="Xem trực tiếp trên app · lưu cho tài khoản Windows hiện tại.",TextWrapping=TextWrapping.Wrap,Margin=new(3,8,3,12)});
